  "biz-r6-k": "Public",
  "biz-r6-v": "Name, category and number of responsible people are visible in the explorer. An account can only be closed when it is empty; the balance is paid out to people beforehand, free of fees.",
  "shop-1-h": "Checkout by QR code",
