  "shop-status": "<strong>Status:</strong> the rules on the chain are built and apply from 1 October 2026. Checkout mode and export in the app are in progress.",
  "lh-label": "Protection against abuse",
  "lh-h2": "Who is a business? We don't need to know.",
  "lh-sub": "A decentralised network cannot check whether a real company stands behind an account, and it should not have to: no registry, no authority, no gatekeeper. Instead, hoarding is expensive in every form and passing money on is cheap in every form. Registering as a business only pays off for those whose money really flows.",
  "lh-list-h": "Every workaround we found, and why it fails",
  "lh-1": "<strong>Registering as a business to get around the 25,000 limit.</strong> The idle-money levy of 1–3 % a month is more expensive than any other form.",
  "lh-2": "<strong>Sending money in circles between your own or friendly firms.</strong> The age travels with the money; between businesses nothing gets younger, however long the circle.",
  "lh-3": "<strong>Paying it back through the owner or a friend.</strong> If the money stayed with that person for less than 30 days, it keeps its age.",
  "lh-4": "<strong>Really parking it with friends for 30 days.</strong> Every person can hold at most 25,000 AEQ and pays the surcharge both ways: about 2–2.5 % per round to save 1–3 %, at full risk.",
  "lh-5": "<strong>Founding many firms for many free amounts.</strong> At most 3 business accounts per person, so at most 6,000 AEQ free.",
  "lh-6": "<strong>Paying yourself as an “employee”.</strong> Payments to responsible people count as withdrawals, not wages.",
  "lh-7": "<strong>Fake wages to friends who exchange and hand back cash.</strong> Wages are free of the exit levy only up to 3,000 AEQ per person and month, and wage totals are public.",
  "lh-8": "<strong>Making money “younger” through the liquidity pool.</strong> Only people can provide liquidity.",
  "lh-9": "<strong>A smart contract as a hiding place.</strong> Contracts are other addresses: at most 1,000 AEQ, 1 % a month.",
  "lh-honest": "<strong>What honestly remains:</strong> no money system in the world can stop many real people from colluding. Here every known collusion costs more than it saves, or is limited to small amounts. Business turnover and wage totals are public, so unusual patterns stand out. Anyone who finds a new gap reports it, and the rules are adjusted.",
  "rm-label": "Roadmap",
  "rm-h2": "What comes next",
  "rm-1-h": "Now: Phase 1",
  "rm-1-p": "Registration with a live face check by two independent matching services. 1,000 AEQ start, basic income every day.",
  "rm-2-h": "1 October 2026",
  "rm-2-p": "The economy rules take effect: three account types, idle-money levy, exit levy, fee-free monthly amounts for people.",
  "rm-3-h": "App for shops",
  "rm-3-p": "Checkout mode with QR code and accounting export.",
  "rm-4-h": "Pilot town",
  "rm-4-p": "5–10 shops (café, bakery, farm shop, hairdresser, workshop) for three months. Measured: how much stays in circulation, how much leaves, how much reaches the basic income.",
  "rm-5-h": "Legal review and real stable coin",
  "rm-5-p": "Before real money: review under the EU crypto regulation (MiCA) and a regulated euro stable coin instead of the test currency tUSD. Only then open more widely.",
  "op-label": "Honestly",
  "op-h2": "What is not finished yet",
  "op-1": "<strong>Test currency only.</strong> Today tUSD is the only currency to exchange into; there is no real euro or dollar exit yet.",
  "op-2": "<strong>Legal review pending.</strong> Whether AEQ and the built-in exchange fall under the EU crypto regulation MiCA must be checked before real money.",
  "op-3": "<strong>Exchange-rate risk.</strong> While AEQ is small, its price fluctuates. For cautious shops, immediate exchange is the answer.",
  "op-4": "<strong>Taxes.</strong> For businesses, AEQ income is business income at its euro value on the day of payment.",
  "op-5": "<strong>The numbers are starting values.</strong> 2,000 AEQ free amount, 30/90 days, 1 %/3 %, 2 %, 1,000 and 3,000 a month: measured in the pilot town, then adjusted.",
  "faq-label": "Questions",
  "faq-h2": "Frequently asked",
  "faq-q1": "Why don't businesses simply get dollars only?",
  "faq-a1": "Then every purchase would be a sale of AEQ. There would hardly be buyers, and the price, and with it the basic income, would keep falling. Circulation only happens if businesses can pass AEQ on themselves: to staff, suppliers and other businesses.",
  "faq-q2": "What changes for me as a person on 1 October 2026?",
  "faq-a2": "For most people nothing, or it gets cheaper: the first 1,000 AEQ you spend each month become free of fees, and the levy on idle money applies only above 5,000 AEQ.",
  "faq-q3": "Is anything burned?",
  "faq-a3": "No. Every fee and every levy goes 100 % to the basic income and returns to all verified people in equal shares.",
  "faq-q4": "Can a business receive the basic income or vote?",
  "faq-a4": "No. Basic income, vote and the fair share belong only to verified people. Behind every business account stand one to ten verified people who are responsible for it.",
  "faq-q5": "What is an “other address”?",
  "faq-a5": "Every address that is neither a verified person nor a business: a visitor's wallet, a tip jar, a simple contract. It may hold at most 1,000 AEQ and pays 1 % a month.",
  "faq-q6": "Why do rules per person work here?",
  "faq-a6": "Every person exists exactly once at Aequitas. A free amount per person cannot be multiplied with more accounts. No other money can do that.",
  "faq-q7": "Has money like this ever worked?",
  "faq-a7": "Yes. Wörgl (Austria, 1932) had money that lost 1 % a month; it circulated so fast that the town built roads and bridges with it until the national bank banned it. The Chiemgauer (Bavaria, since 2003) has a circulation levy and hundreds of shops. The WIR Bank (Switzerland, since 1934) runs settlement money between businesses.",
  "pg-eco-h1": "How it works",
  "pg-eco-sub": "One cycle, three kinds of account, one set of rules, and why the money stays fair.",
  "pg-biz-h1": "Aequitas for businesses",
  "pg-biz-sub": "Take payments without card fees, pay wages free of charge and pass the money on. Only money left idle costs.",
  "pg-road-h1": "Roadmap and questions",
  "pg-road-sub": "Where Aequitas stands, what comes next, and what is honestly still open.",
  "pg-back": "← Back to the overview",
  "fs-note": "<strong>Every limit is a multiple of the fair share.</strong> 1,000 AEQ is what the average person holds, because the money supply is always people × 1,000 AEQ. So 2,000 = 2×, 3,000 = 3×, 5,000 = 5× and 25,000 = 25× the fair share. The limits are not tied to the dollar: if AEQ gains or loses value, everyone's fair share changes with it and the limits keep their meaning.",
  "faq-q8": "Why aren't the limits tied to the dollar?",
  "faq-a8": "Because fairness is about each person's share of all the money, not about dollar amounts. The average person always holds exactly one fair share (1,000 AEQ), and every limit is a multiple of it. A dollar link would need a price source that someone could push, and a rising price would quietly tighten the limits. Only the monthly allowances depend on how much of life is paid in AEQ: after the pilot town, the fee-free monthly amount and the wage allowance are to follow what the median person really spends each month, never less than 1× the fair share.",
