  "ex-cafe-r": "paga 0,8 AEQ al mes",
  "ex-market-h": "Un supermercado que acapara",
  "ex-market-p": "Cada mes pasan 40.000 AEQ, pero 200.000 AEQ se quedan en la cuenta. Primero sale el dinero más antiguo, así que 40.000 AEQ tienen menos de 30 días, 80.000 entre 30 y 90 días y 80.000 más: 80.000 × 1 % + (80.000 − 2.000) × 3 %. Si en cambio paga salarios, el gravamen baja y el dinero llega directamente a las personas.",
