  "ubi-pre": "Следующее равное распределение через",
  "ubi-mid": "· в пуле",
  "how-label": "Регистрация",
  "how-h2": "Три честных шага (Phase 1)",
  "how-sub": "Кошелёк на телефоне, короткая живая съёмка лица и разовое начисление — без банковского счёта.",
  "step1-h": "Снять",
  "step1-p": "Установи кошелёк на телефон и пройди короткую живую съёмку лица. Два независимых сервиса проверяют, что ты ещё не зарегистрирован. Снимки удаляются.",
  "step2-h": "Доказать",
  "step2-p": "Приложение отправляет в сеть доказательство, что ты новый участник, не раскрывая, кто ты.",
  "step3-h": "Получить",
  "step3-p": "1 000 AEQ один раз за успешную регистрацию.",
  "sybil-blurb": "<strong>Sybil / защита:</strong> живая проверка лица (кворум 2 независимых служб) + подписанное подтверждение + nullifier в цепи, тратится один раз. Названные ограничения: счета, созданные до проверки лица (25.08.2026 — почти все из сегодняшних 18), не имеют шаблона лица; порог сравнения ещё не откалиброван на реальных снимках; проверка живости — поворот головы, продвинутые дипфейки остаются остаточным риском; режим долей (<code>MPC</code>) работает в тени, каждая служба по-прежнему хранит целый зашифрованный шаблон.",
  "how-link": "Зарегистрироваться и получить свои 1 000 AEQ →",
  "why-label": "Справедливость",
  "why-h2": "Коэффициент Джини у Bitcoin ~0,85 — выше, чем в любой стране",
  "why-sub": "Предложение = подтверждённые люди × 1 000 AEQ. Gini с живого узла. Go L1 — источник истины реестра (не только зеркальный контракт).",
  "why-link": "Кривая Лоренца, история и сравнение со странами →",
  "disc-title": "Оговорка Phase 1",
  "disc-body": "Phase 1: с 25.08.2026 сервер доказательств отклоняет любую регистрацию без подписанного подтверждения кворума сравнения — второй телефон больше не даёт тому же лицу второй счёт. Что пока не выполняется: счета, созданные до этой даты, не имеют шаблона лица и в принципе могли бы зарегистрироваться снова на новый кошелёк; частота ошибок не откалибрована (нужно ~1 000 импостор-пар); проверка живости — поворот головы, более сильная защита от дипфейков калибруется. Читайте «один человек — один счёт» как «проверено, с названными ограничениями», а не как «невозможно обойти».",
  "oss-line": "<strong>Открытый код:</strong> Ядро цепи публично · сервисы identity/proof частично закрыты в Phase 1.",
  "soc-label": "Социальные сети",
  "soc-h2": "Где говорит сеть",
  "soc-sub": "Объявления, состояние сети и неудобные вопросы &mdash; публично, в обеих.",
  "soc-x-d": "Объявления и то, чем сеть занята на самом деле. Коротко.",
  "soc-tg-d": "Открытая группа: вопросы, операторы узлов и помощь с регистрацией.",
  "foot-launched": "Запущена в июне 2026 года",
  "foot-phase": "Phase 1",
  "foot-quote": "Деньги существуют, потому что существуют люди. Не больше и не меньше.",
  "cmp-v-25k": "25 000 AEQ (25×)",
  "cmp-v-1k": "1 000 AEQ (1×)",
  "eco-label": "Экономика",
  "eco-h2": "Один круговорот, три роли",
  "eco-sub": "Люди получают базовый доход и тратят его. Компании зарабатывают его и передают дальше как зарплату и закупки. Всё, что лежит без движения или уходит из сети, возвращается в базовый доход, а оттуда поровну ко всем.",
  "eco-svg-people": "Люди",
  "eco-svg-biz": "Компании",
  "eco-svg-ubi": "Базовый доход",
  "eco-svg-buy": "покупки",
  "eco-svg-wages": "зарплаты",
  "eco-svg-daily": "ежедневно, всем поровну",
  "eco-svg-levies": "лежащие деньги · выход · комиссии",
  "eco-p1-h": "Деньги создаются только для людей",
  "eco-p1-p": "Каждый проверенный человек один раз получает 1 000 AEQ. Больше никто не создаёт деньги: ни компании, ни валидаторы, ни основатели.",
  "eco-p2-h": "Оборот вознаграждается",
  "eco-p2-p": "Покупки, выплата зарплат и расчёты с поставщиками стоят мало или ничего. Деньги, лежащие сверх ясных пределов, платят небольшой ежемесячный сбор.",
  "eco-p3-h": "Каждый сбор возвращается ко всем",
  "eco-p3-p": "Комиссии за переводы, сборы за лежащие деньги и за выход идут на 100 % в базовый доход, который каждый день выплачивается поровну каждому проверенному человеку.",
  "cmp-label": "Человек или компания?",
  "cmp-h2": "Три вида счетов, одни правила",
  "cmp-sub": "Никто не проверяет, кто вы. Правила делают накопление дорогим в любой форме, а передачу денег дальше дешёвой, поэтому каждый выбирает счёт, который ему действительно подходит.",
  "cmp-col-rule": "Правило",
  "cmp-col-person": "Человек",
  "cmp-col-biz": "Компания",
