  "ubi-label": "Базовый доход",
  "ubi-h2": "Каждый день, всем поровну",
  "ubi-sub": "Для базового дохода деньги не создаются. Он выплачивается только из того, что собирает сеть, и всё собранное выплачивается.",
  "ubi-c1-h": "Старт: 1 000 AEQ",
  "ubi-c1-p": "Каждый проверенный человек один раз получает 1 000 AEQ при регистрации: справедливую долю. Денежная масса всегда равна числу проверенных людей × 1 000 AEQ.",
  "ubi-c2-h": "Ежедневно в 20:00",
  "ubi-c2-p": "Каждый день в 20:00 (по Берлину) пул делится поровну между всеми проверенными людьми. После этого он снова начинается с нуля.",
  "ubi-c3-h": "Откуда он берётся",
  "ubi-c3-p": "Комиссии за переводы (100 %), 30 % комиссий свопа, сбор за лежащие деньги, сбор за выход 2 % и всё, что выше предела 25 000 AEQ.",
