  "ubi-note": "Размер ежедневной доли зависит от того, сколько денег движется: чем больше AEQ в обороте, тем больше возвращается всем.",
  "fee-h": "Комиссия за перевод подробно",
  "fee-col-bal": "Остаток отправителя",
  "fee-col-fee": "Комиссия",
