  "ex-cafe-r": "每月支付 0.8 AEQ",
  "ex-market-h": "一家囤钱的超市",
  "ex-market-p": "每月流经 40,000 AEQ，但有 200,000 AEQ 一直留在账上。最旧的钱先花出，所以 40,000 AEQ 不满 30 天，80,000 在 30–90 天之间，80,000 更久：80,000 × 1% + (80,000 − 2,000) × 3%。如果改为支付工资，费用下降，钱直接到人手中。",
