  "jn-1-h": "开设企业账户",
  "jn-1-p": "一位经过验证的人与企业钱包共同签名。每家企业最多 10 名负责人，每人最多 3 家企业。无需登记机关，也没有审批人。",
  "jn-3-h": "传下去",
