  "toc-prom": "Promesse",
  "toc-fair": "Equità",
  "pg-biz-cta": "Partecipa al pilota",
  "toc-adv": "Vantaggi",
  "toc-join": "Partecipare",
  "toc-bex": "Costi",
  "toc-rules": "Regole",
