  "jn-1-h": "Apri un conto aziendale",
  "jn-1-p": "Una persona verificata e il portafoglio dell’impresa firmano insieme. Fino a 10 responsabili per impresa, al massimo 3 imprese per persona. Nessun registro, nessun intermediario.",
  "jn-3-h": "Rimetti in circolo",
  "jn-3-p": "Gli stipendi alle persone non costano nulla, i pagamenti ai fornitori lo 0,1 %. Il denaro che circola entro 30 giorni non paga mai alcun prelievo.",
