  "how-label": "Kayıt",
  "how-h2": "Üç dürüst adım (Phase 1)",
  "how-sub": "Telefonda cüzdan, kısa bir canlı yüz çekimi ve tek seferlik ödeme — banka hesabı gerekmez.",
