  "step3-h": "Al",
  "step3-p": "Başarılı kayıt başına bir kez 1.000 AEQ.",
  "sybil-blurb": "<strong>Sybil / koruma:</strong> canlı yüz doğrulama (bağımsız servislerden 2'lik çoğunluk) + imzalı onay + zincir üstü nullifier, bir kez harcanır. Belirtilen sınırlar: yüz doğrulamadan önceki hesapların (25.08.2026 — bugünkü 18 hesabın neredeyse tamamı) yüz şablonu yok; eşleşme eşiği henüz gerçek çekimlerle ayarlanmadı; canlılık kontrolü bir baş çevirmedir, gelişmiş deepfake'ler artık risk olarak kalır; pay bölme modu (<code>MPC</code>) gölgede çalışır, her servis hâlâ bütün bir şifrelenmiş şablon tutar.",
  "how-link": "Kaydol ve 1.000 AEQ'nu al →",
  "why-label": "Adalet",
  "why-h2": "Bitcoin'in Gini katsayısı ~0,85 — herhangi bir ülkeden daha yüksek",
  "why-sub": "Arz = doğrulanmış insanlar × 1.000 AEQ. Gini canlı düğümden. Go L1 defterin doğruluk kaynağıdır (yalnızca ayna sözleşme değil).",
  "why-link": "Lorenz eğrisi, geçmiş ve ülke karşılaştırması →",
  "disc-title": "Phase 1 uyarısı",
  "disc-body": "Phase 1: 25.08.2026'dan beri kanıt sunucusu, eşleştirme çoğunluğunun imzalı onayı olmayan her kaydı reddeder — ikinci bir telefon aynı yüze artık ikinci bir hesap vermez. Henüz geçerli olmayan: bu tarihten önceki hesapların yüz şablonu yoktur ve ilke olarak yeni bir cüzdanla yeniden kayıt olabilirler; hata oranları ayarlanmadı (~1.000 sahte çift gerekir); canlılık kontrolü bir baş çevirmedir, daha güçlü deepfake savunmaları ayarlanıyor. “Bir insan, bir hesap”ı “doğrulandı, belirtilen sınırlarla” diye okuyun — “aşılamaz” diye değil.",
  "oss-line": "<strong>Açık kaynak:</strong> Çekirdek zincir açık · kimlik/kanıt servisleri Phase 1'de kısmen özel.",
  "soc-label": "Sosyal medya",
  "soc-h2": "Ağın konuştuğu yer",
  "soc-sub": "Duyurular, zincirin durumu ve zor sorular &mdash; herkese açık, her ikisinde de.",
  "soc-x-d": "Duyurular ve zincirin gerçekte ne yaptığı. Kısa biçim.",
  "soc-tg-d": "Açık grup: sorular, node işletenler ve kayıt olma konusunda yardım.",
  "foot-launched": "Haziran 2026'da başlatıldı",
