  "how-h2": "Trois étapes honnêtes (Phase 1)",
  "how-sub": "Portefeuille sur le téléphone, une courte capture du visage en direct et une allocation unique — sans compte bancaire.",
  "step1-h": "Scanner",
  "step1-p": "Installe le portefeuille sur ton téléphone et fais une courte capture du visage en direct. Deux services indépendants vérifient que tu n’es pas encore inscrit. Les images sont supprimées.",
  "step2-h": "Prouver",
  "step2-p": "L’application envoie à la chaîne une preuve que tu es nouveau, sans révéler qui tu es.",
  "step3-h": "Recevoir",
  "step3-p": "1 000 AEQ une fois par inscription réussie.",
  "sybil-blurb": "<strong>Sybil / protection :</strong> contrôle du visage en direct (quorum 2 de services indépendants) + attestation signée + nullifier on-chain, dépensé une seule fois. Limites nommées : les comptes antérieurs au contrôle du visage (25/08/2026 — presque tous les 18 d'aujourd'hui) n'ont pas de gabarit du visage ; le seuil de comparaison n'est pas encore étalonné sur des captures réelles ; la preuve de vie est un mouvement de tête, les deepfakes avancés restent un risque résiduel ; le mode à parts (<code>MPC</code>) tourne en ombre, chaque service garde encore un gabarit chiffré entier.",
  "how-link": "S'inscrire et recevoir vos 1 000 AEQ →",
  "why-label": "Équité",
  "why-h2": "Le Gini de Bitcoin est ~0,85 — plus élevé que dans n'importe quel pays",
  "why-sub": "Offre = humains vérifiés × 1 000 AEQ. Gini lu du nœud live. Go L1 est la source de vérité du ledger (pas le contrat miroir seul).",
  "why-link": "Courbe de Lorenz, historique et comparaison entre pays →",
  "disc-title": "Avertissement Phase 1",
  "disc-body": "Phase 1 : depuis le 25/08/2026, le serveur de preuves refuse toute inscription sans l'attestation signée du quorum de comparaison — un second téléphone ne donne plus un second compte au même visage. Ce qui n'est pas encore vrai : les comptes antérieurs à cette date n'ont pas de gabarit du visage et pourraient en principe se réinscrire avec un nouveau portefeuille ; les taux d'erreur ne sont pas étalonnés (il faut ~1 000 paires d'imposteurs) ; la preuve de vie est un mouvement de tête, des défenses plus fortes contre les deepfakes sont en étalonnage. Lis « un humain, un compte » comme « vérifié, avec des limites nommées » — pas comme « impossible à contourner ».",
  "oss-line": "<strong>Open source :</strong> Chaîne cœur publique · services identité/preuve en partie privés en Phase 1.",
  "soc-label": "Réseaux sociaux",
  "soc-h2": "Là où le réseau parle",
  "soc-sub": "Les annonces, l'état de la chaîne et les questions qui dérangent &mdash; en public, sur les deux.",
  "soc-x-d": "Les annonces, et ce que la chaîne fait vraiment. Format court.",
