  "eco-p2-h": "La circulation est récompensée",
  "eco-p2-p": "Acheter, verser des salaires et payer des fournisseurs coûte peu ou rien. L'argent qui dort au-delà de limites claires paie un petit prélèvement mensuel.",
  "eco-p3-h": "Chaque prélèvement revient à tous",
