  "ppl-sub": "L'argent le plus juste doit d'abord paraître juste à celui qui a peu.",
  "ppl-1": "<strong>Votre juste part est intouchable.</strong> Les 1 000 premiers AEQ ne paient jamais de prélèvement.",
