  "jn-1-h": "Abra uma conta empresarial",
  "jn-1-p": "Uma pessoa verificada e a carteira da empresa assinam juntas. Até 10 responsáveis por empresa, no máximo 3 empresas por pessoa. Sem cartório, sem intermediários.",
  "jn-3-h": "Repasse",
