  "eco-h2": "دورة واحدة وثلاثة أدوار",
  "eco-sub": "يحصل الناس على الدخل الأساسي وينفقونه. تكسبه الشركات وتمرره رواتبَ ومشتريات. وما يبقى راكدًا أو يغادر الشبكة يعود إلى الدخل الأساسي، ومنه بالتساوي إلى الجميع.",
