  "eco-p1-h": "المال يُنشأ للناس فقط",
  "eco-p1-p": "يحصل كل شخص موثَّق على 1,000 AEQ مرة واحدة. لا أحد غيره يُنشئ المال: لا الشركات ولا المدققون ولا المؤسسون.",
  "eco-p2-h": "التداول يُكافأ",
  "eco-p2-p": "الشراء ودفع الرواتب ودفع الموردين يكلّف قليلًا أو لا شيء. المال الراكد بعد حدود واضحة يدفع اقتطاعًا شهريًا صغيرًا.",
  "eco-p3-h": "كل اقتطاع يعود إلى الجميع",
  "eco-p3-p": "رسوم التحويل واقتطاعات المال الراكد والخروج تذهب بنسبة 100 % إلى الدخل الأساسي، ويُدفع كل يوم بالتساوي لكل شخص موثَّق.",
