  "cmp-r6-f": "أي أحد",
  "cmp-note": "تسري هذه القواعد اعتبارًا من 1 أكتوبر 2026. كل اقتطاع يذهب بنسبة 100 % إلى الدخل الأساسي.",
  "ppl-label": "للأفراد",
  "ppl-h2": "ست وعود لكل شخص",
  "ppl-sub": "يجب أن يبدو المال الأعدل عادلًا أولًا لمن يملك القليل.",
  "ppl-1": "<strong>حصتك العادلة لا تُمس.</strong> أول 1,000 AEQ لا يُقتطع منها شيء أبدًا.",
  "ppl-2": "<strong>الحياة اليومية لا تكلّف شيئًا.</strong> أول 1,000 AEQ تنفقها كل شهر بلا رسوم.",
  "ppl-3": "<strong>الراتب راتب.</strong> حتى 3,000 AEQ من الراتب شهريًا، بالإضافة إلى 1,000 AEQ، تُحوَّل دون اقتطاع.",
  "ppl-4": "<strong>الادخار مسموح.</strong> مدخراتك حتى 5,000 AEQ لا تخسر شيئًا.",
  "ppl-5": "<strong>من يملك أكثر يساهم أكثر.</strong> ترتفع الرسوم فقط مع الأرصدة الكبيرة؛ ويبقى حد 25,000 AEQ.",
  "ppl-6": "<strong>يدفع الأفراد دائمًا أقل من الشركات</strong> مقابل الاحتفاظ والخروج، وكل ما يدفعه أي أحد يعود إلى جميع الناس بالتساوي.",
