  "biz-b2-h": "رواتب بلا رسوم",
  "biz-b2-p": "الرواتب المدفوعة بـ AEQ لا تكلّف شيئًا. يمكن للموظفين تحويل ما يصل إلى 3,000 AEQ من الراتب شهريًا إلى اليورو أو الدولار دون اقتطاع.",
  "biz-b3-h": "بلا سقف للنمو",
  "biz-b3-p": "يمكن للفرد أن يملك 25,000 AEQ كحد أقصى، أما الشركات فليس لها حد ثابت. المال الذي يواصل التداول خلال 30 يومًا لا يكلّف شيئًا أبدًا.",
  "biz-b4-h": "دفع خلال ثوانٍ",
