  "fp-btn": "الوعود الستة والدخل الأساسي وأمثلة ←",
  "st-h2": "المرحلة 1: اختبار علني",
  "st-p": "يعمل Aequitas لكنه لم يكتمل بعد. لا يمكن استبدال AEQ إلا بعملة الاختبار tUSD، والمراجعة القانونية وفق لائحة العملات المشفرة الأوروبية لم تتم بعد، وللتحقق من الوجه حدود معلنة. تسري القواعد الاقتصادية اعتبارًا من 1 أكتوبر 2026.",
