  "eco-svg-levies": "रुका पैसा · निकासी · शुल्क",
  "eco-p1-h": "पैसा सिर्फ़ लोगों के लिए बनता है",
  "eco-p1-p": "हर सत्यापित व्यक्ति को एक बार 1,000 AEQ मिलते हैं। कोई और पैसा नहीं बनाता: न व्यवसाय, न वैलिडेटर, न संस्थापक।",
  "eco-p2-h": "प्रवाह को पुरस्कृत किया जाता है",
  "eco-p2-p": "खरीदारी, वेतन और आपूर्तिकर्ताओं को भुगतान में बहुत कम या कोई खर्च नहीं। स्पष्ट सीमाओं से ज़्यादा रुका पैसा एक छोटी मासिक कटौती देता है।",
  "eco-p3-h": "हर कटौती सबके पास लौटती है",
  "eco-p3-p": "ट्रांसफ़र शुल्क, रुके पैसे की कटौती और निकासी कटौती 100 % बुनियादी आय में जाती हैं, जो हर दिन हर सत्यापित व्यक्ति को बराबर दी जाती है।",
  "cmp-label": "व्यक्ति या व्यवसाय?",
  "cmp-h2": "तीन तरह के खाते, एक ही नियम",
  "cmp-sub": "कोई नहीं जाँचता कि आप कौन हैं। नियम हर तरह की जमाखोरी को महँगा और पैसा आगे बढ़ाना सस्ता बनाते हैं, इसलिए हर कोई वही खाता चुनता है जो सच में उसके लिए सही है।",
  "cmp-col-rule": "नियम",
