  "ubi-c3-h": "कहाँ से आती है",
  "ubi-c3-p": "ट्रांसफ़र शुल्क (100%), स्वैप शुल्क का 30%, रुके पैसे की कटौती, 2% निकासी कटौती और 25,000 AEQ की सीमा से ऊपर का सब कुछ।",
