  "fee-r4-v": "1.1%",
  "fee-note": "शुल्क ऊपर से जुड़ता है: पाने वाले को हमेशा पूरी राशि मिलती है, इसलिए 10 AEQ की कीमत दुकान को ठीक 10 AEQ देती है। 1 अक्टूबर 2026 से कोई व्यक्ति हर महीने जो पहले 1,000 AEQ खर्च करता है वे मुफ़्त हैं, और व्यवसायों से लोगों को दिया गया वेतन कुछ नहीं लेता। व्यवसायों के बीच 0.1% बिना अतिरिक्त शुल्क।",
  "ex-label": "उदाहरण",
  "ex-h2": "असली संख्याओं में इसका मतलब",
  "ex-sub": "चार स्थितियाँ, 1 अक्टूबर 2026 से लागू नियमों के अनुसार गणना।",
  "ex-anna-h": "आन्ना बुनियादी आय से जीती है",
  "ex-anna-p": "उसके पास 1,200 AEQ हैं और वह हर महीने 800 AEQ खर्च करती है। कोई शुल्क नहीं (महीने में 1,000 से कम), कोई कटौती नहीं (5,000 से कम), कोई निकासी कटौती नहीं।",
  "ex-anna-r": "महीने में 0 AEQ देती है",
  "ex-ben-h": "बेन एक कैफ़े में काम करता है",
  "ex-ben-p": "उसे 2,000 AEQ वेतन मिलता है, वह 1,500 AEQ खर्च करता है और किराए के लिए 1,000 AEQ यूरो में बदलता है। मुक्त राशि से ऊपर के 500 AEQ पर शुल्क: 0.5 AEQ। सामान्य स्वैप शुल्क: 1 AEQ। निकासी कटौती नहीं, क्योंकि यह उसका वेतन है।",
  "ex-ben-r": "महीने में 1.5 AEQ देता है",
  "ex-clara-h": "क्लारा के पास 20,000 AEQ हैं",
  "ex-clara-p": "वह हर महीने 3,000 AEQ खर्च करती है और 5,000 AEQ बदलती है। ट्रांसफ़र: 2,000 × 1.1% = 22 AEQ। रुका पैसा: 15,000 × 0.5% = 75 AEQ। बदलना: 4,000 × 2% = 80 AEQ (पहले 1,000 मुफ़्त)। सब बुनियादी आय में जाता है, यानी आन्ना और बेन तक भी।",
  "ex-clara-r": "महीने में 177 AEQ देती है",
  "ex-cafe-h": "एक कैफ़े",
  "ex-cafe-p": "यह हर महीने 3,000 AEQ कमाता है और 1,500 वेतन, 800 आपूर्तिकर्ता को और 600 मालकिन को देता है। पैसा महीने के भीतर आगे बढ़ जाता है, कुछ भी 30 दिन से पुराना नहीं होता, इसलिए रुके पैसे की कटौती नहीं। सिर्फ़ आपूर्तिकर्ता को भुगतान पर 0.1% लगता है।",
  "ex-cafe-r": "महीने में 0.8 AEQ देता है",
  "ex-market-h": "एक सुपरमार्केट जो जमा करता है",
  "ex-market-p": "हर महीने 40,000 AEQ गुज़रते हैं, पर 200,000 AEQ खाते में पड़े रहते हैं। सबसे पुराना पैसा पहले निकलता है, इसलिए 40,000 AEQ 30 दिन से नए, 80,000 30–90 दिन पुराने और 80,000 उससे पुराने हैं: 80,000 × 1% + (80,000 − 2,000) × 3%। अगर वह इसके बजाय वेतन देता है, तो कटौती घटती है और पैसा सीधे लोगों तक पहुँचता है।",
  "ex-market-r": "हर महीने लगभग 3,140 AEQ बुनियादी आय में देता है",
  "ex-hoard-h": "कोई 100,000 AEQ जमा करना चाहता है",
  "ex-hoard-p": "व्यक्ति के रूप में: असंभव, सीमा 25,000 AEQ है। 1,000-1,000 AEQ के 100 अन्य पतों पर: 1% प्रति माह = 1,000 AEQ प्रति माह। “व्यवसाय” के रूप में: दूसरे और तीसरे महीने 980 AEQ प्रति माह, फिर 98,000 × 3% = 2,940 AEQ प्रति माह।",
  "ex-hoard-r": "जमाखोरी किसी भी रूप में फ़ायदेमंद नहीं (लगभग 35% सालाना)",
  "age-h": "पैसा कब नया माना जाता है?",
