  "age-r4-v": "नया",
  "age-note": "व्यवसाय हमेशा अपना सबसे पुराना पैसा पहले खर्च करता है, जो उसके लिए सबसे सस्ता क्रम है। लोगों के लिए उम्र मायने नहीं रखती; इसे सिर्फ़ इसलिए साथ ले जाया जाता है ताकि व्यवसायों को यह सही मिले।",
  "biz-r6-k": "सार्वजनिक",
  "biz-r6-v": "नाम, श्रेणी और ज़िम्मेदार लोगों की संख्या एक्सप्लोरर में दिखती है। खाता सिर्फ़ खाली होने पर बंद हो सकता है; शेष पहले लोगों को बिना शुल्क दिया जाता है।",
  "shop-1-h": "QR कोड से बिलिंग",
  "shop-1-p": "राशि डालें, QR कोड दिखाएँ, ग्राहक स्कैन करके भुगतान करता है और रसीद पाता है। कीमतें AEQ में या मौजूदा दर पर यूरो के बराबर दिखाई जा सकती हैं।",
  "shop-2-h": "लेखा निर्यात",
