  "shop-status": "<strong>स्थिति:</strong> चेन पर नियम बन चुके हैं और 1 अक्टूबर 2026 से लागू हैं। ऐप में बिलिंग मोड और निर्यात पर काम चल रहा है।",
  "lh-label": "दुरुपयोग से सुरक्षा",
  "lh-h2": "व्यवसाय कौन है? हमें यह जानने की ज़रूरत नहीं।",
  "lh-sub": "एक विकेंद्रीकृत नेटवर्क यह जाँच नहीं सकता कि किसी खाते के पीछे असली कंपनी है या नहीं, और उसे ऐसा करना भी नहीं चाहिए: न व्यापार रजिस्टर, न कोई प्राधिकरण, न कोई द्वारपाल। इसके बजाय जमाखोरी हर रूप में महँगी है और पैसा आगे बढ़ाना हर रूप में सस्ता। व्यवसाय के रूप में पंजीकरण सिर्फ़ उन्हीं के लिए फ़ायदेमंद है जिनका पैसा सच में चलता है।",
  "lh-list-h": "हमें मिले सभी चोर-रास्ते, और वे क्यों नाकाम हैं",
  "lh-1": "<strong>25,000 की सीमा से बचने के लिए व्यवसाय के रूप में पंजीकरण।</strong> 1–3% मासिक कटौती किसी भी दूसरे रूप से महँगी है।",
  "lh-2": "<strong>अपनी या दोस्तों की फ़र्मों के बीच पैसा घुमाना।</strong> उम्र पैसे के साथ चलती है; व्यवसायों के बीच कुछ भी नया नहीं होता, घेरा कितना भी लंबा हो।",
  "lh-3": "<strong>मालिक या दोस्त के ज़रिए वापस भेजना।</strong> अगर पैसा उस व्यक्ति के पास 30 दिन से कम रहा, तो उसकी उम्र बनी रहती है।",
  "lh-4": "<strong>सच में 30 दिन दोस्तों के पास पैसा रखना।</strong> हर व्यक्ति अधिकतम 25,000 AEQ रख सकता है और आने-जाने दोनों ओर अतिरिक्त शुल्क देता है: 1–3% बचाने के लिए हर चक्कर में लगभग 2–2.5%, पूरे जोखिम के साथ।",
  "lh-5": "<strong>कई मुक्त राशियों के लिए कई फ़र्में बनाना।</strong> प्रति व्यक्ति अधिकतम 3 व्यवसाय खाते, यानी अधिकतम 6,000 AEQ मुक्त।",
  "lh-6": "<strong>खुद को “कर्मचारी” के रूप में भुगतान।</strong> ज़िम्मेदार लोगों को भुगतान निकासी है, वेतन नहीं।",
  "lh-7": "<strong>दोस्तों को नकली वेतन जो बदलकर नकद लौटा दें।</strong> वेतन प्रति व्यक्ति प्रति माह सिर्फ़ 3,000 AEQ तक निकासी कटौती से मुक्त है, और वेतन के योग सार्वजनिक हैं।",
  "lh-8": "<strong>लिक्विडिटी पूल से पैसे को “नया” बनाना।</strong> लिक्विडिटी सिर्फ़ लोग दे सकते हैं।",
  "lh-9": "<strong>स्मार्ट कॉन्ट्रैक्ट को छिपने की जगह बनाना।</strong> कॉन्ट्रैक्ट अन्य पते हैं: अधिकतम 1,000 AEQ, 1% प्रति माह।",
  "lh-honest": "<strong>ईमानदारी से जो बचता है:</strong> दुनिया की कोई भी मुद्रा प्रणाली बहुत सारे असली लोगों को आपस में मिलीभगत करने से नहीं रोक सकती। यहाँ हर ज्ञात मिलीभगत जितना बचाती है उससे ज़्यादा खर्च करती है, या छोटी रकमों तक सीमित रहती है। व्यवसायों का कारोबार और वेतन के योग सार्वजनिक हैं, इसलिए असामान्य पैटर्न नज़र आते हैं। जो नई कमी पाए, वह बताए, और नियम बदले जाते हैं।",
  "rm-label": "रोडमैप",
  "rm-h2": "आगे क्या है",
  "rm-1-h": "अभी: चरण 1",
  "rm-1-p": "दो स्वतंत्र मिलान सेवाओं द्वारा लाइव चेहरा जाँच के साथ पंजीकरण। 1,000 AEQ शुरुआत, हर दिन बुनियादी आय।",
