  "rm-3-h": "दुकानों के लिए ऐप",
  "rm-3-p": "QR कोड वाला बिलिंग मोड और लेखा निर्यात।",
  "rm-4-h": "पायलट शहर",
  "rm-4-p": "तीन महीने के लिए 5–10 दुकानें (कैफ़े, बेकरी, फ़ार्म दुकान, नाई, वर्कशॉप)। मापा जाएगा: कितना प्रचलन में रहता है, कितना बाहर जाता है, कितना बुनियादी आय तक पहुँचता है।",
  "rm-5-h": "कानूनी समीक्षा और असली स्टेबलकॉइन",
  "rm-5-p": "असली पैसे से पहले: यूरोपीय संघ के क्रिप्टो नियम (MiCA) के अनुसार समीक्षा और परीक्षण मुद्रा tUSD की जगह एक विनियमित यूरो स्टेबलकॉइन। उसके बाद ही बड़े स्तर पर खोलना।",
  "op-label": "सच कहें तो",
  "op-h2": "क्या अभी पूरा नहीं है",
  "op-1": "<strong>सिर्फ़ परीक्षण मुद्रा।</strong> आज बदलने के लिए सिर्फ़ tUSD है; यूरो या डॉलर में असली निकासी अभी नहीं है।",
  "op-2": "<strong>कानूनी समीक्षा बाक़ी।</strong> AEQ और अंतर्निहित विनिमय यूरोपीय संघ के MiCA नियम के अंतर्गत आते हैं या नहीं, यह असली पैसे से पहले जाँचना होगा।",
  "op-3": "<strong>विनिमय दर का जोखिम।</strong> जब तक AEQ छोटा है, इसकी कीमत बदलती रहती है। सतर्क दुकानों के लिए जवाब है तुरंत बदलना।",
  "op-4": "<strong>कर।</strong> व्यवसायों के लिए AEQ आय भुगतान के दिन के यूरो मूल्य पर व्यावसायिक आय है।",
  "op-5": "<strong>संख्याएँ शुरुआती मान हैं।</strong> 2,000 AEQ मुक्त, 30/90 दिन, 1%/3%, 2%, मासिक 1,000 और 3,000: पायलट शहर में मापकर फिर बदले जाएँगे।",
  "faq-label": "सवाल",
  "faq-h2": "अक्सर पूछे जाने वाले सवाल",
  "faq-q1": "व्यवसायों को सीधे सिर्फ़ डॉलर क्यों नहीं मिलते?",
  "faq-a1": "तब हर ख़रीद AEQ की बिक्री होती। ख़रीदार लगभग नहीं होते, और कीमत, और उसके साथ बुनियादी आय, लगातार गिरती। प्रचलन तभी बनता है जब व्यवसाय ख़ुद AEQ आगे दे सकें: कर्मचारियों, आपूर्तिकर्ताओं और दूसरे व्यवसायों को।",
  "faq-q2": "1 अक्टूबर 2026 को एक व्यक्ति के रूप में मेरे लिए क्या बदलता है?",
  "faq-a2": "ज़्यादातर लोगों के लिए कुछ नहीं, या यह सस्ता हो जाता है: हर महीने जो पहले 1,000 AEQ तुम खर्च करते हो वे शुल्क-मुक्त हो जाते हैं, और रुके पैसे की कटौती सिर्फ़ 5,000 AEQ से ऊपर लगती है।",
  "faq-q3": "क्या कुछ जलाया जाता है?",
  "faq-a3": "नहीं। हर शुल्क और हर कटौती 100% बुनियादी आय में जाती है और सभी सत्यापित लोगों को बराबर हिस्सों में लौटती है।",
  "faq-q4": "क्या कोई व्यवसाय बुनियादी आय पा सकता है या वोट दे सकता है?",
  "faq-a4": "नहीं। बुनियादी आय, वोट और उचित हिस्सा सिर्फ़ सत्यापित लोगों का है। हर व्यवसाय खाते के पीछे एक से दस सत्यापित लोग होते हैं जो उसके लिए ज़िम्मेदार हैं।",
  "faq-q5": "“अन्य पता” क्या है?",
  "faq-a5": "हर पता जो न सत्यापित व्यक्ति है न व्यवसाय: किसी आगंतुक का वॉलेट, टिप का डिब्बा, एक सरल कॉन्ट्रैक्ट। यह अधिकतम 1,000 AEQ रख सकता है और 1% प्रति माह देता है।",
  "faq-q6": "यहाँ प्रति व्यक्ति नियम क्यों काम करते हैं?",
  "faq-a6": "Aequitas में हर व्यक्ति ठीक एक बार मौजूद है। प्रति व्यक्ति मुक्त राशि को ज़्यादा खातों से गुणा नहीं किया जा सकता। कोई दूसरा पैसा ऐसा नहीं कर सकता।",
  "faq-q7": "क्या ऐसा पैसा पहले कभी सफल हुआ है?",
  "faq-a7": "हाँ। वर्गल (ऑस्ट्रिया, 1932) के पास ऐसा पैसा था जो हर महीने 1% घटता था; वह इतनी तेज़ी से चला कि नगर ने उससे सड़कें और पुल बनाए, जब तक राष्ट्रीय बैंक ने उसे रोक नहीं दिया। कीमगाउअर (बवेरिया, 2003 से) में प्रचलन कटौती है और सैकड़ों दुकानें हैं। WIR बैंक (स्विट्ज़रलैंड, 1934 से) व्यवसायों के बीच निपटान मुद्रा चलाता है।",
  "pg-eco-h1": "यह कैसे काम करता है",
  "pg-eco-sub": "एक चक्र, तीन तरह के खाते, एक ही नियम, और पैसा निष्पक्ष क्यों रहता है।",
  "pg-biz-h1": "व्यवसायों के लिए Aequitas",
  "pg-biz-sub": "बिना कार्ड शुल्क भुगतान लें, मुफ़्त में वेतन दें और पैसा आगे बढ़ाएँ। सिर्फ़ पड़ा रहने वाला पैसा खर्च करवाता है।",
  "pg-road-h1": "रोडमैप और सवाल",
  "pg-road-sub": "Aequitas कहाँ है, आगे क्या आता है, और ईमानदारी से क्या अभी खुला है।",
  "pg-back": "← अवलोकन पर वापस",
